<?php foreach($data['quarantine'] as $operation): ?><tr data-owner="<?=$escape($cs_owner($operation))?>"><td class="path"><?=$escape($cs_label($operation))?><br><?=$escape($operation['metadata']['path'])?><?php if(!$operation['site_availability']['available']): ?><p class="notice alert alert-info"><?=$escape($operation['site_availability']['message'])?><br>Original root: <?=$escape($operation['metadata']['root']??'Unknown')?></p><?php endif ?></td><td><?=$escape($operation['kind'].' / '.$operation['status'])?></td><td><?php if($operation['site_availability']['available'] && $operation['kind']==='quarantine' && in_array($operation['status'],['prepared','restoring','recovery_required'])): ?><button class="button" data-action="quarantine-recover" data-operation_id="<?=$escape($operation['id'])?>">Recover quarantine operation</button><?php endif ?><?php if($operation['site_availability']['available'] && $operation['status']==='quarantined' && $operation['kind']==='quarantine'): ?><button class="button" data-action="restore" data-operation_id="<?=$escape($operation['id'])?>">Restore original</button><?php endif ?></td></tr><?php endforeach ?>
